import argparse
import base64
import io
import json
import mimetypes
import os
import tarfile
from pathlib import Path

import requests

from workpeg.submit import _looks_secret


DEFAULT_API_BASE = "https://repo.workpeg.com"


EXCLUDED_DIRS = {
    ".git",
    "__pycache__",
    ".pytest_cache",
    ".venv",
    "venv",
    "dist",
    "build",
    # credential stores — never publish these
    ".ssh",
    ".aws",
    ".gnupg",
}

EXCLUDED_SUFFIXES = (".pyc", ".pyo")


def decode_jwt_payload_no_verify(token: str) -> dict:
    try:
        parts = token.split(".")
        if len(parts) != 3:
            raise ValueError("Invalid JWT format")

        payload = parts[1]
        payload += "=" * (-len(payload) % 4)

        return json.loads(base64.urlsafe_b64decode(payload.encode()))
    except Exception as exc:
        print(f"ERROR: Invalid WORKPEG_PK JWT: {exc}", file=os.sys.stderr)
        raise SystemExit(2)


def default_asset_path(
    source_path: Path,
    original_source: str | None = None,
) -> str:
    original_source = original_source or str(source_path)

    if original_source.strip() == ".":
        return "assets"

    if source_path.is_file():
        return source_path.name

    if source_path.is_dir():
        return source_path.name or "assets"

    return source_path.name or "assets"


def build_directory_tar_gz_bytes(path: Path) -> bytes:
    if not path.exists() or not path.is_dir():
        print(f"ERROR: Directory not found: {path}", file=os.sys.stderr)
        raise SystemExit(2)

    out = io.BytesIO()

    with tarfile.open(fileobj=out, mode="w:gz") as archive:
        for item in path.rglob("*"):
            if item.is_dir():
                continue

            rel = item.relative_to(path)

            if any(part in EXCLUDED_DIRS for part in rel.parts):
                continue

            if item.name.endswith(EXCLUDED_SUFFIXES):
                continue

            # Never publish secrets, and never follow a symlink out of the tree.
            if item.is_symlink() or _looks_secret(item.name):
                continue

            archive.add(item, arcname=str(rel))

    return out.getvalue()


def submit_asset(
    *,
    api_base: str,
    peg_id: str,
    token: str,
    asset_path: str,
    source_path: Path,
    exact: bool,
    overwrite: bool,
    timeout_s: int,
) -> dict:
    url = f"{api_base.rstrip('/')}/api/pegs/{peg_id}/cdn/"

    params = {}

    if exact:
        params["exact"] = "true"

    if overwrite:
        params["overwrite"] = "true"

    if source_path.is_dir():
        filename = f"{source_path.name or 'assets'}.tar.gz"
        file_bytes = build_directory_tar_gz_bytes(source_path)
        content_type = "application/gzip"
    else:
        if not source_path.exists():
            print(f"ERROR: File not found: {source_path}", file=os.sys.stderr)
            raise SystemExit(2)

        filename = source_path.name
        file_bytes = source_path.read_bytes()
        content_type = (
            mimetypes.guess_type(filename)[0]
            or "application/octet-stream"
        )

    resp = requests.post(
        url,
        headers={
            "Authorization": f"Bearer {token}",
        },
        params=params,
        data={
            "path": asset_path,
        },
        files={
            "file": (
                filename,
                file_bytes,
                content_type,
            )
        },
        timeout=timeout_s,
    )

    if resp.status_code >= 400:
        try:
            body = resp.json()
        except ValueError:
            body = resp.text

        print(
            f"ERROR: CDN submit failed ({resp.status_code}): {body}",
            file=os.sys.stderr,
        )
        raise SystemExit(1)

    return resp.json()


def build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(
        prog="workpeg cdn submit",
        description="Upload a file or directory to the Workpeg Peg CDN.",
    )

    p.add_argument(
        "source",
        help="File or directory to upload",
    )

    p.add_argument(
        "--path",
        default=None,
        help=(
            "Target CDN path inside the Peg namespace. "
            "Defaults to filename for files, directory name for directories, "
            "or 'assets' when source is '.'."
        ),
    )

    p.add_argument(
        "--api",
        default=None,
        help="Override Workpeg registry API base URL",
    )

    p.add_argument(
        "--exact",
        action="store_true",
        help="Upload archive exactly instead of extracting it",
    )

    p.add_argument(
        "--overwrite",
        action="store_true",
        help="Replace existing CDN assets if they already exist",
    )

    p.add_argument(
        "--timeout",
        type=int,
        default=60,
        help="HTTP request timeout in seconds",
    )

    return p


def main(argv=None) -> None:
    parser = build_parser()
    args = parser.parse_args(argv)

    token = os.getenv("WORKPEG_PK")

    if not token:
        print("ERROR: Missing env var WORKPEG_PK", file=os.sys.stderr)
        raise SystemExit(2)

    payload = decode_jwt_payload_no_verify(token)
    peg_id = payload.get("peg_namespace")

    if not peg_id:
        print("ERROR: JWT missing peg_namespace", file=os.sys.stderr)
        raise SystemExit(2)

    api_base = (
        args.api
        or os.getenv("WORKPEG_API_BASE")
        or DEFAULT_API_BASE
    )

    source_path = Path(args.source).resolve()

    asset_path = args.path or default_asset_path(
        source_path,
        original_source=args.source,
    )

    result = submit_asset(
        api_base=api_base,
        peg_id=peg_id,
        token=token,
        asset_path=asset_path,
        source_path=source_path,
        exact=args.exact,
        overwrite=args.overwrite,
        timeout_s=args.timeout,
    )

    print(json.dumps(result, indent=2, default=str))
